/**
 * Creates an OpenAI LLM client.
 *
 * @remarks
 * Implements the OpenAI Chat Completions API for GPT models.
 * Supports streaming, tool calling, and all standard OpenAI parameters.
 *
 * @param config - Provider configuration including API key and optional base URL.
 * @returns An LLMClient instance configured for OpenAI's API.
 */
function createOpenAIClient(config: ProviderConfig): LLMClient {
  const baseUrl = config.baseUrl ?? "https://api.openai.com/v1";

  const headers = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${config.apiKey}`,
    ...(config.organizationId
      ? { "OpenAI-Organization": config.organizationId }
      : {}),
    ...config.headers,
  };

  const parseJsonResponse = async <T>(
    response: Response,
    errorPrefix: string,
  ): Promise<T> => {
    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(`${errorPrefix}: ${response.status} - ${errorBody}`);
    }

    return (await response.json()) as T;
  };

  return {
    async chat(request: ChatRequest): Promise<ChatResponse> {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          model: request.model,
          messages: formatMessagesForOpenAI(request),
          tools: request.tools?.map(formatToolForOpenAI),
          temperature: request.temperature,
          max_tokens: request.maxTokens,
          top_p: request.topP,
          stop: request.stopSequences,
        }),
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      const data = await parseJsonResponse<OpenAIResponse>(
        response,
        "OpenAI API error",
      );
      return parseOpenAIResponse(data);
    },

    async *chatStream(
      request: ChatRequest,
    ): AsyncGenerator<import("./types.js").ChatStreamChunk, void, unknown> {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          model: request.model,
          messages: formatMessagesForOpenAI(request),
          tools: request.tools?.map(formatToolForOpenAI),
          temperature: request.temperature,
          max_tokens: request.maxTokens,
          top_p: request.topP,
          stop: request.stopSequences,
          stream: true,
        }),
        signal: AbortSignal.timeout(config.timeout ?? 120000),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(`OpenAI API error: ${response.status} - ${errorBody}`);
      }

      if (!response.body) {
        throw new Error("No response body for streaming");
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      const toolCallMap = new Map<
        number,
        { id: string; name: string; arguments: string }
      >();

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() ?? "";

          for (const line of lines) {
            if (line.startsWith("data: ")) {
              const jsonStr = line.slice(6).trim();
              if (!jsonStr || jsonStr === "[DONE]") continue;

              try {
                const data = JSON.parse(jsonStr) as OpenAIStreamChunk;
                const choice = data.choices?.[0];
                const delta = choice?.delta;

                if (delta?.content) {
                  yield { content: delta.content, done: false };
                }

                if (delta?.tool_calls) {
                  for (const tc of delta.tool_calls) {
                    const existing = toolCallMap.get(tc.index);
                    if (existing) {
                      if (tc.function?.arguments) {
                        existing.arguments += tc.function.arguments;
                      }
                    } else {
                      toolCallMap.set(tc.index, {
                        id: tc.id ?? `call_${tc.index}`,
                        name: tc.function?.name ?? "",
                        arguments: tc.function?.arguments ?? "",
                      });
                    }

                    // Yield tool call delta
                    const current = toolCallMap.get(tc.index)!;
                    yield {
                      toolCallDelta: {
                        id: current.id,
                        name: current.name || undefined,
                        arguments: tc.function?.arguments
                          ? tryParseJSON(current.arguments)
                          : undefined,
                      },
                      done: false,
                    };
                  }
                }

                if (choice?.finish_reason) {
                  yield {
                    done: true,
                    finishReason:
                      choice.finish_reason === "tool_calls"
                        ? "tool_calls"
                        : "stop",
                    usage: data.usage
                      ? {
                          promptTokens: data.usage.prompt_tokens,
                          completionTokens: data.usage.completion_tokens,
                          totalTokens: data.usage.total_tokens,
                        }
                      : undefined,
                  };
                }
              } catch {
                // Skip invalid JSON
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }
    },

    async listModels(): Promise<ModelInfo[]> {
      const response = await fetch(`${baseUrl}/models`, {
        headers,
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      const data = await parseJsonResponse<{
        data: Array<{ id: string; owned_by: string }>;
      }>(response, "OpenAI API error");
      return data.data
        .filter(
          (m) =>
            m.id.startsWith("gpt-") ||
            /^o\d/.test(m.id) ||
            m.id.startsWith("ft:"),
        )
        .map((m) => ({
          id: m.id,
          name: m.id,
          description: `Owned by: ${m.owned_by}`,
        }));
    },

    async uploadFile(request: UploadFileRequest): Promise<UploadedFile> {
      const fileData = await readFile(request.path);
      const formData = new FormData();
      formData.append("purpose", request.purpose);
      formData.append(
        "file",
        new Blob([fileData], { type: "application/jsonl" }),
        basename(request.path),
      );

      const response = await fetch(`${baseUrl}/files`, {
        method: "POST",
        headers: {
          Authorization: headers.Authorization,
          ...(config.organizationId
            ? { "OpenAI-Organization": config.organizationId }
            : {}),
          ...config.headers,
        },
        body: formData,
        signal: AbortSignal.timeout(config.timeout ?? 120000),
      });

      const data = await parseJsonResponse<OpenAIFileObject>(
        response,
        "OpenAI file upload error",
      );
      return parseOpenAIFile(data);
    },

    async createFineTuningJob(
      request: CreateFineTuningJobRequest,
    ): Promise<FineTuningJob> {
      const response = await fetch(`${baseUrl}/fine_tuning/jobs`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          model: request.model,
          training_file: request.trainingFile,
          validation_file: request.validationFile,
          suffix: request.suffix,
          method: request.hyperparameters
            ? {
                type: "supervised",
                supervised: {
                  hyperparameters: formatFineTuningHyperparameters(
                    request.hyperparameters,
                  ),
                },
              }
            : undefined,
        }),
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      const data = await parseJsonResponse<OpenAIFineTuningJob>(
        response,
        "OpenAI fine-tuning error",
      );
      return parseOpenAIFineTuningJob(data);
    },

    async listFineTuningJobs(): Promise<FineTuningJob[]> {
      const response = await fetch(`${baseUrl}/fine_tuning/jobs`, {
        headers,
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      const data = await parseJsonResponse<{
        data: OpenAIFineTuningJob[];
      }>(response, "OpenAI fine-tuning error");

      return data.data.map(parseOpenAIFineTuningJob);
    },

    async getFineTuningJob(jobId: string): Promise<FineTuningJob> {
      const response = await fetch(`${baseUrl}/fine_tuning/jobs/${jobId}`, {
        headers,
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      const data = await parseJsonResponse<OpenAIFineTuningJob>(
        response,
        "OpenAI fine-tuning error",
      );
      return parseOpenAIFineTuningJob(data);
    },

    async listFineTuningEvents(jobId: string): Promise<FineTuningJobEvent[]> {
      const response = await fetch(
        `${baseUrl}/fine_tuning/jobs/${jobId}/events`,
        {
          headers,
          signal: AbortSignal.timeout(config.timeout ?? 60000),
        },
      );

      const data = await parseJsonResponse<{
        data: OpenAIFineTuningJobEvent[];
      }>(response, "OpenAI fine-tuning error");

      return data.data.map(parseOpenAIFineTuningJobEvent);
    },
  };
}

// OpenAI types
interface OpenAIFileObject {
  id: string;
  bytes: number;
  created_at: number;
  filename: string;
