function formatMessagesForOpenAI(request: ChatRequest) {
  const messages: Array<{
    role: string;
    content: string | null;
    tool_calls?: Array<{
      id: string;
      type: string;
      function: { name: string; arguments: string };
    }>;
    tool_call_id?: string;
  }> = [];

  if (request.systemPrompt) {
    messages.push({ role: "system", content: request.systemPrompt });
  }

  for (const msg of request.messages) {
    if (msg.role === "tool" && msg.toolResults) {
      for (const result of msg.toolResults) {
        messages.push({
          role: "tool",
          tool_call_id: result.toolCallId,
          content: result.error ?? result.content,
        });
      }
    } else if (msg.role === "assistant") {
      messages.push({
        role: "assistant",
        content: msg.content,
        tool_calls: msg.toolCalls?.map((tc) => ({
          id: tc.id,
          type: "function",
          function: { name: tc.name, arguments: JSON.stringify(tc.arguments) },
        })),
      });
    } else {
      messages.push({ role: msg.role, content: msg.content });
    }
  }

  return messages;
}

function formatToolForOpenAI(tool: import("../tools/types.js").ToolDefinition) {
  return {
    type: "function",
    function: {
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
    },
  };
}

function parseOpenAIResponse(data: OpenAIResponse): ChatResponse {
  const choice = data.choices[0];
  const message = choice.message;

  const toolCalls = message.tool_calls?.map((tc) => ({
    id: tc.id,
    name: tc.function.name,
    arguments: tryParseJSON(tc.function.arguments) ?? {},
  }));

  return {
    content: message.content,
    toolCalls,
    usage: data.usage
      ? {
          promptTokens: data.usage.prompt_tokens,
          completionTokens: data.usage.completion_tokens,
          totalTokens: data.usage.total_tokens,
        }
      : undefined,
    model: data.model,
    finishReason: toolCalls && toolCalls.length > 0 ? "tool_calls" : "stop",
  };
}

function parseOpenAIFile(data: OpenAIFileObject): UploadedFile {
  return {
    id: data.id,
    filename: data.filename,
    bytes: data.bytes,
    purpose: data.purpose,
    createdAt: data.created_at,
