function parseOpenAIFineTuningJobEvent(
  data: OpenAIFineTuningJobEvent,
): FineTuningJobEvent {
  return {
    id: data.id,
    createdAt: data.created_at,
    level: data.level,
    message: data.message,
    type: data.type,
  };
}

function tryParseJSON(str: string): Record<string, unknown> | undefined {
  try {
    return JSON.parse(str);
  } catch {
    return undefined;
  }
}

// ============================================================================
// Anthropic Provider
// ============================================================================

/**
 * Creates an Anthropic LLM client.
 *
 * @remarks
 * Implements the Anthropic Messages API for Claude models.
 * Supports streaming, tool use, and extended thinking.
 *
 * @param config - Provider configuration including API key.
 * @returns An LLMClient instance configured for Anthropic's API.
 */
function createAnthropicClient(config: ProviderConfig): LLMClient {
  const baseUrl = config.baseUrl ?? "https://api.anthropic.com/v1";

  const headers = {
    "Content-Type": "application/json",
    "x-api-key": config.apiKey ?? "",
    "anthropic-version": "2023-06-01",
    ...config.headers,
  };

  return {
    async chat(request: ChatRequest): Promise<ChatResponse> {
      const response = await fetch(`${baseUrl}/messages`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          model: request.model,
          max_tokens: request.maxTokens ?? 4096,
          system: request.systemPrompt,
          messages: formatMessagesForAnthropic(request),
          tools: request.tools?.map(formatToolForAnthropic),
          temperature: request.temperature,
          top_p: request.topP,
          stop_sequences: request.stopSequences,
        }),
        signal: AbortSignal.timeout(config.timeout ?? 60000),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(
          `Anthropic API error: ${response.status} - ${errorBody}`,
        );
      }

      const data = (await response.json()) as AnthropicResponse;
      return parseAnthropicResponse(data);
    },

    async *chatStream(
      request: ChatRequest,
    ): AsyncGenerator<import("./types.js").ChatStreamChunk, void, unknown> {
      const response = await fetch(`${baseUrl}/messages`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          model: request.model,
          max_tokens: request.maxTokens ?? 4096,
          system: request.systemPrompt,
          messages: formatMessagesForAnthropic(request),
          tools: request.tools?.map(formatToolForAnthropic),
          temperature: request.temperature,
          top_p: request.topP,
          stop_sequences: request.stopSequences,
          stream: true,
        }),
        signal: AbortSignal.timeout(config.timeout ?? 120000),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(
          `Anthropic API error: ${response.status} - ${errorBody}`,
        );
      }

      if (!response.body) {
        throw new Error("No response body for streaming");
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      const toolCalls: Array<{
        id: string;
        name: string;
        input: Record<string, unknown>;
      }> = [];
      let currentToolUse: {
        id: string;
        name: string;
        inputJson: string;
      } | null = null;

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() ?? "";

          for (const line of lines) {
            if (line.startsWith("data: ")) {
              const jsonStr = line.slice(6).trim();
              if (!jsonStr) continue;

              try {
                const event = JSON.parse(jsonStr) as AnthropicStreamEvent;

                switch (event.type) {
                  case "content_block_start":
                    if (
                      event.content_block?.type === "tool_use" &&
                      event.content_block.id &&
                      event.content_block.name
                    ) {
                      currentToolUse = {
                        id: event.content_block.id,
                        name: event.content_block.name,
                        inputJson: "",
                      };
                    }
                    break;

                  case "content_block_delta":
                    if (
                      event.delta?.type === "text_delta" &&
                      event.delta.text
                    ) {
                      yield { content: event.delta.text, done: false };
                    } else if (
                      event.delta?.type === "input_json_delta" &&
                      currentToolUse
                    ) {
                      currentToolUse.inputJson +=
                        event.delta.partial_json ?? "";
                    }
                    break;

                  case "content_block_stop":
                    if (currentToolUse) {
                      const parsedInput =
                        tryParseJSON(currentToolUse.inputJson) ?? {};
                      toolCalls.push({
                        id: currentToolUse.id,
                        name: currentToolUse.name,
                        input: parsedInput,
                      });
                      yield {
                        toolCallDelta: {
                          id: currentToolUse.id,
                          name: currentToolUse.name,
                          arguments: parsedInput,
                        },
                        done: false,
                      };
                      currentToolUse = null;
                    }
                    break;

                  case "message_stop":
                    yield {
                      done: true,
                      finishReason:
                        toolCalls.length > 0 ? "tool_calls" : "stop",
                    };
                    break;

                  case "message_delta":
                    if (event.usage) {
                      yield {
                        done: true,
                        finishReason:
                          toolCalls.length > 0 ? "tool_calls" : "stop",
                        usage: {
                          promptTokens: 0,
                          completionTokens: event.usage.output_tokens,
                          totalTokens: event.usage.output_tokens,
                        },
                      };
                    }
                    break;
                }
              } catch {
                // Skip invalid JSON
              }
            }
          }
        }
      } finally {
        reader.releaseLock();
      }
    },

    async listModels(): Promise<ModelInfo[]> {
      // Anthropic doesn't have a models endpoint, return known models
      return [
        {
          id: "claude-sonnet-4-20250514",
          name: "Claude Sonnet 4",
          description: "Latest Claude Sonnet model",
        },
        {
          id: "claude-opus-4-20250514",
          name: "Claude Opus 4",
          description: "Latest Claude Opus model",
        },
        {
          id: "claude-3-5-sonnet-20241022",
          name: "Claude 3.5 Sonnet",
          description: "High performance model",
        },
        {
          id: "claude-3-5-haiku-20241022",
          name: "Claude 3.5 Haiku",
          description: "Fast and efficient model",
        },
        {
          id: "claude-3-opus-20240229",
          name: "Claude 3 Opus",
          description: "Most capable Claude 3 model",
        },
      ];
    },
  };
}

// Anthropic types
interface AnthropicResponse {
  id: string;
  type: string;
  role: string;
  content: Array<
    | { type: "text"; text: string }
    | {
        type: "tool_use";
        id: string;
        name: string;
        input: Record<string, unknown>;
      }
  >;
  model: string;
  stop_reason: string;
  usage: { input_tokens: number; output_tokens: number };
}

interface AnthropicStreamEvent {
  type: string;
  content_block?: { type: string; id?: string; name?: string; text?: string };
  delta?: { type: string; text?: string; partial_json?: string };
  usage?: { output_tokens: number };
}

function formatMessagesForAnthropic(request: ChatRequest) {
  const messages: Array<{
    role: "user" | "assistant";
    content:
      | string
      | Array<{
          type: string;
          tool_use_id?: string;
          content?: string;
          id?: string;
          name?: string;
          input?: Record<string, unknown>;
        }>;
  }> = [];

  for (const msg of request.messages) {
    if (msg.role === "user") {
      messages.push({ role: "user", content: msg.content });
    } else if (msg.role === "assistant") {
      if (msg.toolCalls && msg.toolCalls.length > 0) {
        const content: Array<{
          type: string;
          text?: string;
          id?: string;
          name?: string;
          input?: Record<string, unknown>;
        }> = [];
        if (msg.content) {
          content.push({ type: "text", text: msg.content });
        }
        for (const tc of msg.toolCalls) {
          content.push({
            type: "tool_use",
            id: tc.id,
            name: tc.name,
            input: tc.arguments,
          });
        }
        messages.push({ role: "assistant", content });
      } else {
        messages.push({ role: "assistant", content: msg.content });
      }
    } else if (msg.role === "tool" && msg.toolResults) {
      const content = msg.toolResults.map((result) => ({
        type: "tool_result",
        tool_use_id: result.toolCallId,
        content: result.error ?? result.content,
      }));
      messages.push({ role: "user", content });
    }
  }

  return messages;
}

function formatToolForAnthropic(
  tool: import("../tools/types.js").ToolDefinition,
) {
  return {
    name: tool.name,
    description: tool.description,
    input_schema: tool.parameters,
  };
}

function parseAnthropicResponse(data: AnthropicResponse): ChatResponse {
  let content: string | null = null;
  const toolCalls: Array<{
    id: string;
    name: string;
    arguments: Record<string, unknown>;
  }> = [];

  for (const block of data.content) {
    if (block.type === "text") {
      content = block.text;
    } else if (block.type === "tool_use") {
      toolCalls.push({
        id: block.id,
        name: block.name,
        arguments: block.input,
      });
    }
  }

  return {
    content,
    toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
    usage: {
      promptTokens: data.usage.input_tokens,
      completionTokens: data.usage.output_tokens,
      totalTokens: data.usage.input_tokens + data.usage.output_tokens,
    },
    model: data.model,
    finishReason: toolCalls.length > 0 ? "tool_calls" : "stop",
  };
}

