import { appendFileSync, mkdirSync, existsSync } from "fs";
import { readFile } from "fs/promises";
import { join } from "path";
import { basename } from "path";
import { homedir } from "os";
/**
 * Infers the LLM provider from a model name.
 *
 * @remarks
 * Uses naming conventions to determine the provider:
 * - Models starting with 'gemini-' are Google models
 * - Models starting with 'gpt-' or 'o1' or 'o3' are OpenAI models
 * - Models starting with 'claude-' are Anthropic models
 * - All other models are assumed to be Ollama (local) models
 *
 * @param model - The model name to infer provider from
 * @returns The inferred LLMProvider
 */
export function inferProviderFromModel(model) {
    if (model.startsWith("ft:")) {
        const baseModel = model.slice(3).split(":")[0];
        return inferProviderFromModel(baseModel);
    }
    if (model.startsWith("gemini-")) {
        return "google";
    }
    if (model.startsWith("gpt-") || /^o\d/.test(model)) {
        return "openai";
    }
    if (model.startsWith("claude-")) {
        return "anthropic";
    }
    // Assume Ollama for all other models (tinyllama, llama3, mistral, etc.)
    return "ollama";
}
// Debug log file path
const DEBUG_LOG_DIR = join(homedir(), ".beans", "logs");
const DEBUG_LOG_FILE = join(DEBUG_LOG_DIR, "debug.log");
const DEFAULT_RATE_LIMIT_CONFIG = {
    requestsPerMinute: 60, // Default for paid tier (free tier is 15 RPM)
    maxRetries: 3,
    initialBackoffMs: 1000,
};
/**
 * Simple token bucket rate limiter
 */
class RateLimiter {
    tokens;
    lastRefill;
    maxTokens;
    refillRate; // tokens per ms
    constructor(requestsPerMinute) {
        this.maxTokens = requestsPerMinute;
        this.tokens = requestsPerMinute;
        this.lastRefill = Date.now();
        this.refillRate = requestsPerMinute / 60000; // per millisecond
    }
    refill() {
        const now = Date.now();
        const elapsed = now - this.lastRefill;
        const tokensToAdd = elapsed * this.refillRate;
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;
    }
    async acquire() {
        this.refill();
        if (this.tokens >= 1) {
            this.tokens -= 1;
            return;
        }
        // Calculate wait time until we have a token
        const waitMs = Math.ceil((1 - this.tokens) / this.refillRate);
        await sleep(waitMs);
        this.refill();
        this.tokens -= 1;
    }
    getAvailableTokens() {
        this.refill();
        return this.tokens;
    }
}
function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}
/**
 * Wraps a fetch call with rate limiting and retry logic
 */
async function fetchWithRateLimit(rateLimiter, config, fetchFn, onRetry) {
    let lastError = null;
    for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
        // Wait for rate limiter before making request
        await rateLimiter.acquire();
        try {
            const response = await fetchFn();
            if (response.status === 429) {
                // Rate limited - extract retry-after if available
                const retryAfter = response.headers.get("retry-after");
                let waitMs = config.initialBackoffMs * Math.pow(2, attempt);
                if (retryAfter) {
                    // Retry-After can be seconds or a date
                    const parsed = parseInt(retryAfter, 10);
                    if (!isNaN(parsed)) {
                        waitMs = parsed * 1000;
                    }
                }
                // Cap wait time at 60 seconds
                waitMs = Math.min(waitMs, 60000);
                if (attempt < config.maxRetries) {
                    onRetry?.(attempt + 1, waitMs);
                    await sleep(waitMs);
                    continue;
                }
                // Final attempt failed
                const errorBody = await response.text();
                throw new Error(`Rate limit exceeded after ${config.maxRetries} retries: ${errorBody}`);
            }
            return response;
        }
        catch (error) {
            lastError = error instanceof Error ? error : new Error(String(error));
            // Don't retry non-rate-limit errors
            if (!lastError.message.includes("429") &&
                !lastError.message.includes("rate")) {
                throw lastError;
            }
            if (attempt < config.maxRetries) {
                const waitMs = config.initialBackoffMs * Math.pow(2, attempt);
                onRetry?.(attempt + 1, waitMs);
                await sleep(waitMs);
            }
        }
    }
    throw lastError ?? new Error("Rate limit exceeded");
}
// Global rate limiter instance for Google API (shared across all requests)
let googleRateLimiter = null;
function getGoogleRateLimiter(config) {
    if (!googleRateLimiter) {
        const rpm = config?.requestsPerMinute ?? DEFAULT_RATE_LIMIT_CONFIG.requestsPerMinute;
        googleRateLimiter = new RateLimiter(rpm);
    }
    return googleRateLimiter;
}
function ensureLogDir() {
    if (!existsSync(DEBUG_LOG_DIR)) {
        mkdirSync(DEBUG_LOG_DIR, { recursive: true });
    }
}
function writeDebugLog(content) {
    ensureLogDir();
    const timestamp = new Date().toISOString();
    appendFileSync(DEBUG_LOG_FILE, `[${timestamp}]\n${content}\n\n`);
}
/**
 * Creates an LLM client for the specified provider.
 *
 * @remarks
 * This is the main factory function for creating provider-specific LLM clients.
 * It implements the factory pattern to abstract away provider differences and
 * return a unified LLMClient interface regardless of the underlying provider.
 *
 * Supported providers:
 * - **google**: Google Gemini API
 * - **ollama**: Ollama local inference server
 *
 * Each provider client implements the same LLMClient interface with `chat()` and
 * `listModels()` methods, handling provider-specific request formatting, response
 * parsing, and error handling internally.
 *
 * @param provider - The LLM provider to create a client for (google or ollama).
 * @param config - Provider-specific configuration including API keys, base URLs,
