/**
 * Creates an Anthropic LLM client.
 *
 * @remarks
 * Implements the Anthropic Messages API for Claude models.
 * Supports streaming, tool use, and extended thinking.
 *
 * @param config - Provider configuration including API key.
 * @returns An LLMClient instance configured for Anthropic's API.
 */
function createAnthropicClient(config) {
    const baseUrl = config.baseUrl ?? "https://api.anthropic.com/v1";
    const headers = {
        "Content-Type": "application/json",
        "x-api-key": config.apiKey ?? "",
        "anthropic-version": "2023-06-01",
        ...config.headers,
    };
    return {
        async chat(request) {
            const response = await fetch(`${baseUrl}/messages`, {
                method: "POST",
                headers,
                body: JSON.stringify({
                    model: request.model,
                    max_tokens: request.maxTokens ?? 4096,
                    system: request.systemPrompt,
                    messages: formatMessagesForAnthropic(request),
                    tools: request.tools?.map(formatToolForAnthropic),
                    temperature: request.temperature,
                    top_p: request.topP,
                    stop_sequences: request.stopSequences,
                }),
                signal: AbortSignal.timeout(config.timeout ?? 60000),
            });
            if (!response.ok) {
                const errorBody = await response.text();
                throw new Error(`Anthropic API error: ${response.status} - ${errorBody}`);
            }
            const data = (await response.json());
            return parseAnthropicResponse(data);
        },
        async *chatStream(request) {
            const response = await fetch(`${baseUrl}/messages`, {
                method: "POST",
                headers,
                body: JSON.stringify({
                    model: request.model,
                    max_tokens: request.maxTokens ?? 4096,
                    system: request.systemPrompt,
                    messages: formatMessagesForAnthropic(request),
                    tools: request.tools?.map(formatToolForAnthropic),
                    temperature: request.temperature,
                    top_p: request.topP,
                    stop_sequences: request.stopSequences,
                    stream: true,
                }),
                signal: AbortSignal.timeout(config.timeout ?? 120000),
            });
            if (!response.ok) {
                const errorBody = await response.text();
                throw new Error(`Anthropic API error: ${response.status} - ${errorBody}`);
            }
            if (!response.body) {
                throw new Error("No response body for streaming");
            }
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let buffer = "";
            const toolCalls = [];
            let currentToolUse = null;
            try {
                while (true) {
                    const { done, value } = await reader.read();
                    if (done)
                        break;
                    buffer += decoder.decode(value, { stream: true });
                    const lines = buffer.split("\n");
                    buffer = lines.pop() ?? "";
                    for (const line of lines) {
                        if (line.startsWith("data: ")) {
                            const jsonStr = line.slice(6).trim();
                            if (!jsonStr)
                                continue;
                            try {
                                const event = JSON.parse(jsonStr);
                                switch (event.type) {
                                    case "content_block_start":
                                        if (event.content_block?.type === "tool_use" &&
                                            event.content_block.id &&
                                            event.content_block.name) {
                                            currentToolUse = {
                                                id: event.content_block.id,
                                                name: event.content_block.name,
                                                inputJson: "",
                                            };
                                        }
                                        break;
                                    case "content_block_delta":
                                        if (event.delta?.type === "text_delta" &&
                                            event.delta.text) {
                                            yield { content: event.delta.text, done: false };
                                        }
                                        else if (event.delta?.type === "input_json_delta" &&
                                            currentToolUse) {
                                            currentToolUse.inputJson +=
                                                event.delta.partial_json ?? "";
                                        }
                                        break;
                                    case "content_block_stop":
                                        if (currentToolUse) {
                                            const parsedInput = tryParseJSON(currentToolUse.inputJson) ?? {};
                                            toolCalls.push({
                                                id: currentToolUse.id,
                                                name: currentToolUse.name,
                                                input: parsedInput,
                                            });
                                            yield {
                                                toolCallDelta: {
                                                    id: currentToolUse.id,
                                                    name: currentToolUse.name,
                                                    arguments: parsedInput,
                                                },
                                                done: false,
                                            };
                                            currentToolUse = null;
                                        }
                                        break;
                                    case "message_stop":
                                        yield {
                                            done: true,
                                            finishReason: toolCalls.length > 0 ? "tool_calls" : "stop",
                                        };
                                        break;
                                    case "message_delta":
                                        if (event.usage) {
                                            yield {
                                                done: true,
                                                finishReason: toolCalls.length > 0 ? "tool_calls" : "stop",
                                                usage: {
                                                    promptTokens: 0,
                                                    completionTokens: event.usage.output_tokens,
                                                    totalTokens: event.usage.output_tokens,
                                                },
                                            };
                                        }
                                        break;
                                }
                            }
                            catch {
                                // Skip invalid JSON
                            }
                        }
                    }
                }
            }
            finally {
                reader.releaseLock();
            }
        },
